mapper.update:
{CALL
    DECLARE
    v_sql varchar2(500);
    BEGIN
    v_sql :=
    'CREATE SEQUENCE ${tableName}_SEQ START WITH 1  MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
    execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(RCV_DATE)';
        execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(MONUMBER)';
        execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(STATUS)';
    execute immediate v_sql;

    END
    }
